css:
:host {
  --bg-1: #edf0e6;
  --bg-2: #e4dac7;
  --bg-3: #cddbeb;
  --text-main: #143254;
  --text-soft: rgba(20, 50, 84, 0.68);
  --glass: rgba(248, 242, 229, 0.72);
  --glass-strong: rgba(249, 244, 235, 0.9);
  --navy-strong: #0d3257;
  --navy-mid: #214463;
  --teal-main: #18b7b7;
  --gold-main: #c79a3e;
  --gold-soft: #edd7a2;
  --tile-edge: rgba(246, 234, 212, 0.92);
  --shadow-lg: 0 28px 60px rgba(8, 18, 31, 0.18);
  --shadow-md: 0 16px 34px rgba(8, 18, 31, 0.12);
  --radius-xl: 34px;
  --radius-lg: 28px;
  --radius-md: 22px;
  --radius-sm: 18px;
}

* {
  box-sizing: border-box;
}

:host,[data-module-body] {
  margin: 0;
  min-height: 100%;
  font-family: "Manrope", sans-serif;
  color: var(--text-main);
  background:
    radial-gradient(circle at 18% 16%, rgba(255, 255, 255, 0.72), transparent 22%),
    radial-gradient(circle at 82% 24%, rgba(90, 119, 255, 0.34), transparent 24%),
    radial-gradient(circle at 12% 80%, rgba(104, 231, 209, 0.26), transparent 22%),
    linear-gradient(145deg, var(--bg-1) 0%, var(--bg-2) 43%, var(--bg-3) 100%);
  overflow: hidden;
}

[data-module-body] {
  position: relative;
  min-height: 100vh;
  min-height: 100dvh;
}

[data-module-body].folder-open {
  overflow: hidden;
}

.wallpaper,
.halo {
  position: fixed;
  inset: 0;
  pointer-events: none;
}

.wallpaper {
  background:
    radial-gradient(circle at 50% 0%, rgba(255, 255, 255, 0.72), transparent 28%),
    radial-gradient(circle at 78% 18%, rgba(19, 74, 122, 0.16), transparent 24%),
    radial-gradient(circle at 18% 72%, rgba(199, 154, 62, 0.16), transparent 26%);
  opacity: 0.92;
}

.halo {
  filter: blur(18px);
  opacity: 0.68;
}

.halo--one {
  inset: -12% auto auto -10%;
  width: 42vw;
  height: 42vw;
  max-width: 420px;
  max-height: 420px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.78), rgba(255, 255, 255, 0));
}

.halo--two {
  inset: auto -8% -14% auto;
  width: 46vw;
  height: 46vw;
  max-width: 460px;
  max-height: 460px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(13, 50, 87, 0.2), rgba(13, 50, 87, 0));
}

.iphone-shell {
  position: relative;
  z-index: 1;
  min-height: 100vh;
  min-height: 100dvh;
  display: flex;
  height: 100dvh;
  overflow: hidden;
  padding:
    max(10px, env(safe-area-inset-top, 0px))
    max(12px, env(safe-area-inset-right, 0px))
    max(18px, env(safe-area-inset-bottom, 0px))
    max(12px, env(safe-area-inset-left, 0px));
}

.springboard {
  width: min(100%, 430px);
  margin: 0 auto;
  height: 100%;
  padding-bottom: 6px;
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: 8px;
  min-height: 0;
  overflow: hidden;
}

.glass-card {
  background: var(--glass);
  border: 1px solid rgba(255, 255, 255, 0.7);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.55),
    0 20px 48px rgba(8, 18, 31, 0.12);
  backdrop-filter: blur(22px) saturate(1.2);
  -webkit-backdrop-filter: blur(22px) saturate(1.2);
}

.hero-card {
  position: relative;
  overflow: hidden;
  border-radius: 28px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  padding: 18px 16px;
  background: linear-gradient(90deg, rgba(255, 210, 120, 0.4) 0%, rgba(232, 217, 187, 0.96) 100%);
  border: 2px solid rgba(255, 159, 67, 0.72);
  box-shadow: 0 22px 40px rgba(181, 100, 4, 0.22);
}

.hero-card::before {
  content: none;
}

.hero-card::after {
  content: none;
}

.hero-card > .hero-logo-wrap,
.hero-card > .hero-copy,
.hero-card > .hero-side-icon {
  position: relative;
  z-index: 1;
}

.hero-logo-wrap {
  position: relative;
  width: 118px;
  height: 118px;
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.94);
  display: grid;
  place-items: center;
  flex: 0 0 auto;
}

.hero-logo-link {
  text-decoration: none;
  transition: transform 180ms ease, box-shadow 180ms ease;
}

.hero-logo-link:hover,
.hero-logo-link:focus-visible {
  transform: translateY(-1px) scale(1.01);
  box-shadow: 0 14px 28px rgba(8, 18, 31, 0.16);
}

.hero-logo {
  width: 104px;
  height: 104px;
  object-fit: contain;
}

.home-logo-label {
  position: absolute;
  z-index: 2;
  right: 8px;
  bottom: 4px;
  left: 8px;
  padding: 2px 4px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.92);
  color: #1762a1;
  font-size: 0.58rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  line-height: 1.1;
  text-align: center;
}

/* Premium 3D logo button for the title. */
.hero-side-icon {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.95);
  background: linear-gradient(145deg, #ffffff 0%, #e8f2f7 52%, #b9d0dc 100%);
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.48), 0 16px 28px rgba(12, 49, 72, 0.26), inset 0 2px 0 rgba(255, 255, 255, 0.98), inset 0 -8px 14px rgba(37, 78, 101, 0.14);
  transition: transform 160ms ease, filter 160ms ease, box-shadow 160ms ease;
}

.hero-side-icon:hover,
.hero-side-icon:focus-visible {
  filter: saturate(1.08);
  transform: translateY(-2px) scale(1.015);
}

.hero-side-icon:active {
  transform: translateY(1px) scale(0.98);
}

.hero-side-icon__image {
  position: relative;
  z-index: 1;
  filter: drop-shadow(0 8px 9px rgba(20, 52, 75, 0.2));
}

.hero-copy {
  min-width: 0;
  display: grid;
  justify-items: center;
  text-align: center;
}

.hero-kicker {
  display: block;
  margin: 0 auto;
  padding: 7px 14px;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(255, 248, 220, 0.98) 0%, rgba(248, 221, 152, 0.96) 100%);
  box-shadow: 0 10px 22px rgba(181, 100, 4, 0.16);
  color: rgba(125, 77, 10, 0.98);
  font-size: 1rem;
  font-weight: 900;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.hero-copy h1 {
  margin: 10px 0 0;
  color: var(--ink);
  font-size: clamp(2.1rem, 7vw, 2.9rem);
  line-height: 0.9;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.hero-side-icon {
  order: -1;
  width: 112px;
  height: 112px;
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.92);
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  box-shadow: 0 12px 24px rgba(8, 18, 31, 0.12);
}

.hero-side-icon__image {
  width: 98px;
  height: 98px;
  object-fit: contain;
}

.premium-title-logo {
  position: relative;
  pointer-events: none;
  cursor: default;
  isolation: isolate;
  overflow: hidden;
  border: 2px solid rgba(255, 255, 255, 0.96) !important;
  background: linear-gradient(145deg, #ffffff 0%, #e9f5fb 48%, #a8c7d6 100%) !important;
  box-shadow: 0 0 0 3px rgba(116, 190, 226, 0.28), 0 18px 30px rgba(8, 35, 55, 0.34), inset 0 3px 0 rgba(255, 255, 255, 0.98), inset 0 -10px 16px rgba(33, 77, 101, 0.22) !important;
}

.premium-title-logo::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: -38% -24% auto;
  height: 66%;
  border-radius: 50%;
  background: linear-gradient(105deg, transparent 16%, rgba(255, 255, 255, 0.94) 50%, transparent 84%);
  transform: rotate(-9deg);
  pointer-events: none;
}

.premium-title-logo:hover,
.premium-title-logo:focus-visible { transform: translateY(-3px) scale(1.025); filter: saturate(1.12) brightness(1.04); }
.premium-title-logo:active { transform: translateY(2px) scale(0.975); }
.premium-title-logo > img { position: relative; z-index: 1; filter: drop-shadow(0 9px 10px rgba(12, 43, 62, 0.28)); }

.hero__logo-lockup {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  height: 118px;
  min-height: 118px;
  padding: 7px 10px 36px;
  border-radius: 22px;
  background:
    radial-gradient(circle at 15% 12%, rgba(245, 236, 219, 0.24), transparent 32%),
    radial-gradient(circle at 84% 94%, rgba(199, 154, 62, 0.18), transparent 35%),
    linear-gradient(122deg, #0d3257 0%, #214463 52%, #2e5f7d 100%);
  border: 2px solid rgba(199, 154, 62, 0.82);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.42),
    inset 0 -14px 28px rgba(2, 31, 53, 0.24),
    0 18px 34px rgba(13, 50, 87, 0.28);
}

.hero__logo-image {
  position: relative;
  z-index: 1;
  width: min(100%, 82px);
  max-height: 74px;
  object-fit: contain;
  height: auto;
  filter: drop-shadow(0 18px 34px rgba(0, 0, 0, 0.18));
}

.hero__logo-ribbon {
  position: absolute;
  z-index: 2;
  bottom: 6px;
  left: 50%;
  transform: translateX(-50%);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: min(88%, 246px);
  min-height: 28px;
  padding: 6px 14px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.24);
  background:
    linear-gradient(135deg, rgba(199, 154, 62, 0.96), rgba(181, 100, 4, 0.94)),
    linear-gradient(180deg, rgba(255, 255, 255, 0.16), rgba(255, 255, 255, 0));
  box-shadow:
    0 18px 32px rgba(122, 73, 12, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.22);
  color: #ffffff;
  font-size: 0.6rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  white-space: nowrap;
}

.hero__logo-link {
  color: inherit;
  text-decoration: none;
  cursor: pointer;
  transition: transform 180ms ease, filter 180ms ease, box-shadow 180ms ease;
}

.hero__logo-link:hover,
.hero__logo-link:focus-visible {
  transform: translateY(-1px);
  filter: saturate(1.05);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.42),
    inset 0 -14px 28px rgba(2, 31, 53, 0.24),
    0 20px 38px rgba(13, 50, 87, 0.34);
}

.hero__logo-link:focus-visible {
  outline: 3px solid rgba(77, 124, 255, 0.3);
  outline-offset: 3px;
}

.icon-grid-wrap {
  margin-top: 0;
  border-radius: 28px;
  padding: 8px 8px 10px;
  display: flex;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
}

.icon-grid {
  width: 100%;
  flex: 1 1 auto;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-template-rows: repeat(5, minmax(0, 1fr));
  gap: 8px 6px;
  align-content: stretch;
  justify-items: stretch;
  align-items: stretch;
}

.main-return-dock {
  width: 100%;
  margin-top: auto;
  padding-bottom: max(2px, env(safe-area-inset-bottom, 0px));
  display: flex;
  justify-content: center;
}

.module-link-strip {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 9px;
  min-height: 126px;
  margin: 8px 0;
  padding: 8px;
  border: 1px solid rgba(255, 255, 255, 0.86);
  border-radius: 26px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.86), rgba(218, 232, 239, 0.72));
  box-shadow: 0 18px 34px rgba(8, 18, 31, 0.14), inset 0 1px 0 rgba(255, 255, 255, 0.96), inset 0 -8px 18px rgba(109, 145, 166, 0.1);
}

.module-link-card {
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-rows: 1fr auto;
  justify-items: center;
  min-width: 0;
  min-height: 108px;
  overflow: hidden;
  padding: 5px 4px 8px;
  border: 1px solid rgba(255, 255, 255, 0.94);
  border-radius: 20px;
  background: linear-gradient(160deg, rgba(255, 255, 255, 0.98) 0%, rgba(235, 244, 248, 0.94) 48%, rgba(199, 218, 228, 0.9) 100%);
  color: #1762a1;
  text-decoration: none;
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.58), 0 10px 18px rgba(26, 73, 98, 0.16), inset 0 1px 0 rgba(255, 255, 255, 0.98), inset 0 -6px 12px rgba(51, 96, 119, 0.1);
  transition: transform 160ms ease, filter 160ms ease, box-shadow 160ms ease;
}

.module-link-card::before {
  content: "";
  position: absolute;
  z-index: -1;
  top: -44%;
  left: -22%;
  width: 144%;
  height: 68%;
  border-radius: 50%;
  background: linear-gradient(100deg, transparent 12%, rgba(255, 255, 255, 0.72) 48%, transparent 82%);
  transform: rotate(-8deg);
  pointer-events: none;
}

.module-link-card:hover,
.module-link-card:focus-visible {
  filter: saturate(1.08);
  transform: translateY(-2px) scale(1.01);
  box-shadow: 0 0 0 2px rgba(219, 241, 255, 0.9), 0 14px 24px rgba(23, 98, 161, 0.2), inset 0 1px 0 rgba(255, 255, 255, 1), inset 0 -6px 12px rgba(51, 96, 119, 0.08);
}

.module-link-card:active {
  transform: translateY(1px) scale(0.97);
  filter: saturate(0.98);
}

.module-link-card__image {
  display: block;
  width: min(100%, 92px);
  height: 82px;
  object-fit: contain;
}

.module-link-card span {
  padding: 3px 7px;
  border: 1px solid rgba(23, 98, 161, 0.2);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.64);
  color: #1762a1;
  font-size: 0.6rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  line-height: 1;
  text-align: center;
}

.footer-banner {
  width: 100%;
  margin-top: 6px;
  padding: 9px 10px;
  border-radius: 18px;
  text-align: center;
  color: #ffffff;
  background: linear-gradient(135deg, rgba(13, 50, 87, 0.98), rgba(33, 68, 99, 0.96));
  font-size: 0.63rem;
  font-weight: 800;
  box-shadow: 0 14px 28px rgba(8, 12, 23, 0.22);
}

.main-return-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 52px;
  padding: 14px 22px;
  border-radius: 999px;
  border: 1px solid rgba(199, 154, 62, 0.34);
  background: linear-gradient(135deg, rgba(13, 50, 87, 0.98), rgba(33, 68, 99, 0.96));
  color: #f7f9ff;
  text-decoration: none;
  font-size: 0.82rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  box-shadow: 0 18px 34px rgba(8, 12, 23, 0.34);
}

.main-return-button:hover {
  transform: translateY(-1px);
  box-shadow: 0 22px 38px rgba(8, 12, 23, 0.4);
}

.home-button-icon {
  width: 19px;
  height: 19px;
  margin-right: 7px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.9;
}

.main-return-button {
  background: linear-gradient(135deg, #b9e8ff 0%, #83c9f3 54%, #5b9fe0 100%);
  border-color: rgba(70, 145, 211, 0.45);
  color: #0d3d68;
  box-shadow: 0 16px 32px rgba(71, 137, 194, 0.24), inset 0 1px 0 rgba(255, 255, 255, 0.62);
}

.main-return-button:hover {
  background: linear-gradient(135deg, #c8eeff 0%, #96d5f8 54%, #6ba9e7 100%);
}

.app-icon {
  appearance: none;
  border: 0;
  background: transparent;
  color: inherit;
  padding: 0;
  width: 100%;
  height: 100%;
  display: grid;
  justify-items: center;
  align-content: stretch;
  gap: 0;
  text-align: center;
  cursor: pointer;
  transition: transform 170ms ease, filter 170ms ease;
}

.app-icon:hover,
.app-icon:focus-visible {
  transform: translateY(-3px) scale(1.02);
  filter: saturate(1.05);
}

.app-icon:focus-visible {
  outline: none;
}

.app-icon__text {
  position: relative;
  --icon-a: #0d3257;
  --icon-b: #214463;
  --icon-c: #18b7b7;
  width: 100%;
  height: 100%;
  min-height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 12px 10px;
  border-radius: 25px;
  background:
    radial-gradient(circle at 24% 18%, rgba(255, 255, 255, 0.78), transparent 22%),
    radial-gradient(circle at 82% 20%, rgba(237, 215, 162, 0.22), transparent 26%),
    linear-gradient(150deg, rgba(246, 234, 212, 0.22), rgba(255, 255, 255, 0.04)),
    linear-gradient(145deg, var(--icon-a), var(--icon-b) 58%, var(--icon-c));
  border: 1px solid rgba(246, 234, 212, 0.76);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.72),
    inset 0 -16px 24px rgba(0, 0, 0, 0.16),
    0 18px 30px rgba(13, 50, 87, 0.18);
  color: var(--text-main);
  font-size: 0.76rem;
  font-weight: 900;
  line-height: 1.02;
  letter-spacing: 0.01em;
  white-space: pre-line;
  text-wrap: balance;
  text-shadow: none;
  overflow: hidden;
}

.app-icon__text::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.16), transparent 30%, rgba(8, 20, 37, 0.12));
  pointer-events: none;
}

.app-icon::after {
  content: none;
}

.app-icon__text.is-compact {
  font-size: 0.66rem;
}

.app-icon__text.is-dense {
  font-size: 0.58rem;
}

.app-icon__text.is-dense {
  letter-spacing: 0;
}

.folder-overlay {
  position: fixed;
  inset: 0;
  z-index: 20;
  display: grid;
  place-items: center;
  padding: 18px;
  overflow: hidden;
}

.folder-overlay.hidden {
  pointer-events: none;
}

.folder-overlay.hidden .folder-overlay__backdrop {
  opacity: 0;
}

.folder-overlay.hidden .folder-sheet {
  opacity: 0;
  transform: translateY(18px) scale(0.94);
}

.folder-overlay__backdrop {
  position: absolute;
  inset: 0;
  border: 0;
  background: rgba(4, 10, 18, 0.34);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  opacity: 1;
  transition: opacity 200ms ease;
}

.folder-sheet {
  position: relative;
  width: min(100%, 420px);
  height: min(72dvh, 640px);
  max-height: calc(100dvh - 36px);
  min-height: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  border-radius: 34px;
  padding: 16px 16px 18px;
  background:
    radial-gradient(circle at top right, rgba(255, 255, 255, 0.9), transparent 28%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(244, 248, 255, 0.9));
  border: 1px solid rgba(255, 255, 255, 0.82);
  box-shadow: var(--shadow-lg);
  transition: opacity 200ms ease, transform 200ms ease;
}

.folder-sheet__bar {
  width: 52px;
  height: 5px;
  border-radius: 999px;
  margin: 0 auto 12px;
  background: rgba(11, 22, 38, 0.18);
}

.folder-sheet__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.folder-sheet__close {
  appearance: none;
  border: 0;
  min-height: 38px;
  padding: 10px 16px;
  border-radius: 999px;
  background: rgba(9, 24, 42, 0.08);
  color: rgba(7, 18, 32, 0.72);
  font: inherit;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.folder-sheet__time {
  font-size: 0.95rem;
  font-weight: 900;
  color: rgba(7, 18, 32, 0.72);
}

.folder-sheet__hero {
  flex: 1 1 auto;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 14px;
  align-items: center;
  padding: 14px;
  border-radius: 28px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.84), rgba(240, 245, 255, 0.7));
  border: 1px solid rgba(255, 255, 255, 0.7);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.78),
    0 12px 24px rgba(8, 18, 31, 0.08);
}

.folder-sheet__glyph {
  --icon-a: #0d3257;
  --icon-b: #214463;
  --icon-c: #18b7b7;
  width: 88px;
  height: 88px;
  display: grid;
  place-items: center;
  padding: 10px;
  border-radius: 28px;
  background:
    radial-gradient(circle at 22% 18%, rgba(255, 255, 255, 0.76), transparent 24%),
    radial-gradient(circle at 78% 20%, rgba(237, 215, 162, 0.18), transparent 28%),
    linear-gradient(160deg, rgba(246, 234, 212, 0.2), rgba(255, 255, 255, 0.04)),
    linear-gradient(145deg, var(--icon-a), var(--icon-b) 62%, var(--icon-c));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.72),
    inset 0 -18px 24px rgba(0, 0, 0, 0.16),
    0 18px 28px rgba(13, 50, 87, 0.16);
  color: var(--text-main);
  font-size: 0.68rem;
  font-weight: 900;
  line-height: 1.06;
  letter-spacing: 0.012em;
  white-space: pre-line;
  text-align: center;
  text-wrap: balance;
}

.folder-sheet__copy {
  min-width: 0;
}

.folder-sheet__eyebrow {
  margin: 0 0 4px;
  font-size: 0.68rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(7, 18, 32, 0.52);
}

.folder-sheet__copy h2 {
  margin: 0;
  font-size: clamp(1.1rem, 3.9vw, 1.6rem);
  line-height: 1.04;
  letter-spacing: -0.04em;
}

.folder-sheet__copy p:last-child {
  margin: 6px 0 0;
  color: var(--text-soft);
  font-size: 0.84rem;
  line-height: 1.35;
}

.folder-sheet__actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 18px;
  flex: 0 0 auto;
}

.folder-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 76px;
  padding: 12px 14px;
  border-radius: 18px;
  border: 1px solid rgba(246, 234, 212, 0.42);
  text-decoration: none;
  color: var(--text-main);
  font-size: 0.78rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  box-shadow: 0 16px 28px rgba(13, 50, 87, 0.18);
  transition: transform 180ms ease, filter 180ms ease, box-shadow 180ms ease;
}

.folder-action:hover,
.folder-action:focus-visible {
  transform: translateY(-2px);
  filter: saturate(1.04);
}

.folder-action--gestor {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.42), rgba(255, 255, 255, 0)),
    linear-gradient(135deg, #dce8ee, #b9d4e1 56%, #8fb9cf);
}

.folder-action--equipe {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.46), rgba(255, 255, 255, 0)),
    linear-gradient(135deg, #d8ebe8, #bfded9 64%, #9fc9c1);
}

.folder-action:focus-visible,
.folder-sheet__close:focus-visible,
.app-icon:focus-visible {
  outline: 3px solid rgba(77, 124, 255, 0.24);
  outline-offset: 3px;
}

@media (max-width: 680px) {
  .module-link-strip {
    gap: 5px;
    min-height: 104px;
    margin: 5px 0;
    padding: 5px;
    border-radius: 18px;
  }

  .module-link-card {
    min-height: 92px;
    padding: 4px 2px 6px;
    border-radius: 14px;
  }

  .module-link-card__image {
    width: min(100%, 70px);
    height: 66px;
  }

  .module-link-card span {
    padding: 2px 4px;
    font-size: 0.52rem;
  }
}

@media (max-width: 480px) {
  .springboard {
    width: min(100%, 390px);
    min-height: calc(100dvh - 28px);
  }

  .hero-card,
  .icon-grid-wrap {
    border-radius: 24px;
  }

  .hero__logo-lockup {
    height: 102px;
    min-height: 102px;
    padding: 6px 8px 34px;
  }

  .hero__logo-image {
    width: min(100%, 72px);
    max-height: 62px;
  }

  .hero__logo-ribbon {
    bottom: 5px;
    min-width: calc(100% - 14px);
    padding: 7px 10px;
    font-size: 0.54rem;
    letter-spacing: 0.1em;
    white-space: normal;
  }

  .icon-grid {
    gap: 8px 5px;
  }

  .app-icon__text {
    min-height: 0;
    font-size: 0.66rem;
  }

  .app-icon__text.is-compact {
    font-size: 0.6rem;
  }

  .app-icon__text.is-dense {
    font-size: 0.54rem;
  }

  .folder-sheet {
    border-radius: 30px;
    padding: 14px 14px 16px;
  }

  .folder-sheet__hero {
    grid-template-columns: 1fr;
    justify-items: center;
    text-align: center;
  }

  .folder-sheet__glyph {
    width: 78px;
    height: 78px;
    border-radius: 24px;
    font-size: 0.56rem;
  }
}

/* Keep the management home action next to the footer like Escala Semanal. */
.iphone-shell {
  padding-bottom: max(12px, env(safe-area-inset-bottom, 0px));
}

.springboard {
  width: min(100%, 430px);
  gap: 8px;
  padding-bottom: 0;
}

.icon-grid-wrap {
  flex: 1 1 auto;
  min-height: 0;
}

.main-return-dock {
  position: relative;
  top: 10px;
  margin-top: 0;
  margin-bottom: -10px;
  flex: 0 0 auto;
}

.footer-banner {
  margin-top: 0;
  flex: 0 0 auto;
}

/* Use the same background surface as Escala Semanal. */
:host,[data-module-body] {
  background:
    radial-gradient(circle at top right, rgba(255, 255, 255, 0.12), transparent 22%),
    radial-gradient(circle at left 80%, rgba(255, 183, 77, 0.12), transparent 18%),
    linear-gradient(180deg, #0d3257 0%, #214463 44%, #eee4d1 100%);
}

.wallpaper,
.halo {
  display: none;
}

@media (max-width: 480px) {
  .hero-card {
    grid-template-columns: 102px minmax(0, 1fr);
    gap: 10px;
    padding: 18px 12px;
  }

  .hero-logo-wrap {
    width: 102px;
    height: 102px;
    border-radius: 22px;
  }

  .hero-logo {
    width: 90px;
    height: 90px;
  }

  .hero-kicker {
    padding: 6px 10px;
    font-size: 0.82rem;
    letter-spacing: 0.08em;
  }

  .hero-copy h1 {
    margin-top: 8px;
    font-size: 2rem;
    letter-spacing: 0.05em;
  }

  .hero-side-icon {
    width: 94px;
    height: 94px;
    border-radius: 22px;
  }

  .hero-side-icon__image {
    width: 82px;
    height: 82px;
  }
}

/* Show which authenticated email is active in the app and its modals. */
[data-auth-user]:not([hidden]) {
  padding-left: 20px;
  background-image: radial-gradient(circle, #22c55e 0 6px, transparent 7px);
  background-position: 0 50%;
  background-repeat: no-repeat;
  background-size: 16px 16px;
}

.hero-copy > [data-auth-user]:not([hidden]) {
  padding-left: 18px;
  background-position: 0 50%;
}

/* Balanced Gestão home: every block shares the fixed modal proportionally. */
.springboard {
  gap: 6px;
}

.icon-grid-wrap {
  padding: 8px;
}

.icon-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-template-rows: repeat(5, minmax(0, 1fr));
  gap: 7px 6px;
  align-content: stretch;
  align-items: stretch;
}

.app-icon,
.app-icon__text {
  min-width: 0;
  min-height: 0;
}

.app-icon__text {
  height: 100%;
  padding: 10px 8px;
  border-radius: 22px;
}

.module-link-strip {
  margin: 0;
}

.footer-banner {
  min-height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
}

@media (max-width: 480px) {
  .icon-grid-wrap {
    padding: 7px;
  }

  .icon-grid {
    gap: 6px 5px;
  }

  .app-icon__text {
    padding: 8px 6px;
    border-radius: 19px;
  }

  .module-link-strip {
    margin: 0;
  }
}


/* Authentication indicator: red until the shared session is effectively validated. */
[data-auth-user][data-authenticated="false"]:not([hidden]) {
  --auth-dot-color: #ef4444;
  background-image: radial-gradient(circle, #ef4444 0 6px, transparent 7px);
}

.hero-copy > [data-auth-user][data-authenticated="false"]:not([hidden])::before {
  background: #ef4444;
  box-shadow: 0 0 0 2px rgba(239, 68, 68, 0.18), 0 1px 4px rgba(153, 27, 27, 0.24);
}
